// fn add(x: i64, y: i64) -> i64 { return x + y }
private parseFunctionDef(): AST.VFunction | null {
  if (!this.check('fn')) return null;
  this.advance();

  const name = this.current().text;
  this.advance();

  // 파라미터 파싱: (x: i64, y: i64)
  this.consume('(');
  const params = [];
  while (!this.check(')')) {
    const paramName = this.current().text;
    this.advance();
    this.consume(':');
    const paramType = this.current().text;
    this.advance();
    params.push({ name: paramName, typeAnnotation: paramType });
    if (!this.check(')')) this.consume(',');
  }
  this.consume(')');

  // 반환 타입: -> i64
  let returnType = 'void';
  if (this.check('->')) {
    this.advance();
    returnType = this.current().text;
    this.advance();
  }

  // 본문: { ... }
  this.consume('{');
  const body = [];
  while (!this.check('}')) {
    const stmt = this.parseStatement();
    if (stmt) body.push(stmt);
  }
  this.consume('}');

  return {
    type: 'VFunction',
    name,
    params,
    returnType,
    body
  };
}
```

