**파일**: `src/nexus/codegen/nexus-codegen.ts`

```ts
private genVFunctionDef(fn: AST.VFunction): void {
  // 함수 선언
  const returnType = this.mapVType(fn.returnType || 'void');
  const paramList = fn.params
    .map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`)
    .join(', ');

  this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
  this.indent++;

  // 함수 본문
  for (const stmt of fn.body) {
    if (stmt.type === 'ReturnStatement') {
      const expr = this.genVExpression(stmt.value);
      this.writeC(`return ${expr};`);
    } else {
      this.genVStatement(stmt);
    }
  }

  this.indent--;
  this.writeC(`}`);
  this.writeC('');
}
```

### Step 3: For-range 루프 (30분)

```ts
// for i in 0..10 { ... }
