  typeAnnotation?: string; // i64, string 등 (선택)
  line: number;
  column: number;
}

/**
 * V 모드 함수
 * 예: fn add(x: i64, y: i64) -> i64 { return x + y }
 */
export interface VFunction extends ASTNode {
  type: 'VFunction';
  name: string;
  params: Parameter[];
  returnType?: string; // -> 타입
  body: Statement[];
  mode: 'v';
}

/**
 * Python 모드 함수
 * 예: def add(a, b): return a + b
 */
export interface PyFunction extends ASTNode {
  type: 'PyFunction';
  name: string;
  params: Parameter[];
  returnType?: string; // -> 타입 (선택)
  body: Statement[];
  mode: 'python';
}

/**
 * Return 문장
 */
export interface ReturnStatement extends ASTNode {
  type: 'Return';
  value?: Expression;
}

/**
 * 할당 문장
 */
export interface AssignStatement extends ASTNode {
  type: 'Assign';
  name: string;
  value: Expression;
}

/**
 * 표현식 문장
 */
export interface ExprStatement extends ASTNode {
  type: 'ExprStatement';
  expression: Expression;
}

/**
 * If 문장
 */
export interface IfStatement extends ASTNode {
  type: 'IfStatement';
  condition: Expression;
  thenBranch: Statement[];
  elseBranch?: Statement[];
}

/**
 * While 루프
 */
export interface WhileStatement extends ASTNode {
  type: 'WhileStatement';
  condition: Expression;
  body: Statement[];
}

/**
 * For-In 루프
 * for i in range(10) { body }
 * for item in arr { body }
 */
export interface ForStatement extends ASTNode {
  type: 'ForStatement';
  variable: string;     // 루프 변수명
  iterable: Expression; // range(10) CallExpr 또는 arr Identifier
  body: Statement[];
}

/**
 * 문장 타입 (Return, Assign, ExprStatement, IfStatement, WhileStatement, ForStatement)
 */
export type Statement = ReturnStatement | AssignStatement | ExprStatement | IfStatement | WhileStatement | ForStatement;

/**
 * 숫자 리터럴
 */
export interface NumberLiteral extends ASTNode {
  type: 'Number';
  value: number | string; // 16진수, 이진수 표현 가능
}

/**
 * 문자열 리터럴
 */
export interface StringLiteral extends ASTNode {
  type: 'String';
  value: string;
}

/**
 * 식별자 (변수명, 함수명 등)
 */
export interface Identifier extends ASTNode {
  type: 'Identifier';
  name: string;
}

/**
 * 이항 연산식
 * 예: x + y, a * b
 */
export interface BinaryExpr extends ASTNode {
  type: 'BinaryExpr';
  left: Expression;
  operator: string; // +, -, *, /, &&, ||, ==, !=, <, >, <=, >=
  right: Expression;
}

/**
 * 함수 호출 표현식
 * 예: foo(), Module::func()
 */
export interface CallExpr extends ASTNode {
  type: 'Call';
  callee: Expression | string; // Identifier 또는 Module::func 형식 문자열
  args: Expression[];
}

/**
 * 배열 리터럴
 * 예: [1, 2, 3], []
 */
export interface ArrayLiteral extends ASTNode {
  type: 'Array';
  elements: Expression[];
}

/**
 * 배열 접근
 * 예: arr[0], items[i]
 */
export interface ArrayAccess extends ASTNode {
  type: 'ArrayAccess';
  object: Expression;
  index: Expression;
}

/**
 * 멤버 접근
 * 예: arr.length, obj.property
 */
export interface MemberAccess extends ASTNode {
  type: 'MemberAccess';
  object: Expression;
  property: string;
}

/**
 * 구조체 필드 정의
 */
export interface StructField {
  name: string;
  typeAnnotation: string;
  line: number;
  column: number;
}

/**
 * 구조체 정의
 * 예: struct Person { name: string, age: i64 }
 */
export interface StructDef extends ASTNode {
  type: 'StructDef';
  name: string;
  fields: StructField[];
  mode: 'v';
}

/**
 * 구조체 리터럴
 * 예: Person { name: "Alice", age: 30 }
 */
export interface StructLiteral extends ASTNode {
  type: 'StructLiteral';
  name: string;
  fields: { [key: string]: Expression };
}

/**
 * 표현식 타입
 */
export type Expression = NumberLiteral | StringLiteral | Identifier | BinaryExpr | CallExpr | ArrayLiteral | ArrayAccess | MemberAccess | StructLiteral;

/**
 * 프로그램 (최상위 노드)
 */
export interface Program {
  type: 'Program';
  body: Array<VFunction | PyFunction | StructDef | Statement>;
}

